import { DateTime } from "./src/luxon.js";

// reference: build a Date with setUTCFullYear (handles years 0-99 literally)
function ref(y, m, d) {
  const dt = new Date(0);
  dt.setUTCFullYear(y, m - 1, d);
  dt.setUTCHours(0, 0, 0, 0);
  return dt;
}
function refPlusDays(y, m, d, n) {
  const dt = ref(y, m, d);
  dt.setUTCDate(dt.getUTCDate() + n);
  return [dt.getUTCFullYear(), dt.getUTCMonth() + 1, dt.getUTCDate()];
}
function refPlusMonths(y, m, d, n) {
  // luxon semantics: clamp day to days in target month
  const total = y * 12 + (m - 1) + n;
  const ny = Math.floor(total / 12);
  const nm = total - ny * 12 + 1;
  const dim = new Date(Date.UTC(2000, nm, 0)).getUTCDate(); // month length independent of year except feb
  const isLeap = (yy) => yy % 4 === 0 && (yy % 100 !== 0 || yy % 400 === 0);
  const len = nm === 2 ? (isLeap(ny) ? 29 : 28) : dim;
  return [ny, nm, Math.min(d, len)];
}

let bad = 0;
for (let y = -3; y <= 105; y++) {
  for (let m = 1; m <= 12; m++) {
    for (let d = 1; d <= 31; d++) {
      const probe = DateTime.utc(y, m, d);
      if (!probe.isValid) continue;
      for (let n = -40; n <= 40; n++) {
        const got = probe.plus({ days: n });
        const [ey, em, ed] = refPlusDays(y, m, d, n);
        if (got.year !== ey || got.month !== em || got.day !== ed) {
          if (bad++ < 25) console.log(`DAYS y=${y} m=${m} d=${d} n=${n}: got ${got.year}-${got.month}-${got.day} want ${ey}-${em}-${ed}`);
        }
      }
      for (let n = -14; n <= 14; n++) {
        const got = probe.plus({ months: n });
        const [ey, em, ed] = refPlusMonths(y, m, d, n);
        if (got.year !== ey || got.month !== em || got.day !== ed) {
          if (bad++ < 25) console.log(`MONTHS y=${y} m=${m} d=${d} n=${n}: got ${got.year}-${got.month}-${got.day} want ${ey}-${em}-${ed}`);
        }
      }
    }
  }
}
console.log("total mismatches:", bad);
