// covert a calendar object to a local timestamp (epoch, but with the offset baked in)
export function objToLocalTS(obj) {
  // for legacy reasons, the Date constructor interprets years between 0 and 99 as 19XX.
  // We can't just use Date.UTC and then shift the resulting year back, because the
  // intermediate year can be a different kind of leap year (e.g. 1900 vs 0, or 2000 vs
  // 100), which throws off the month/day overflow arithmetic. So set the year directly.
  const d = new Date(0);
  d.setUTCFullYear(obj.year, obj.month - 1, obj.day);
  d.setUTCHours(obj.hour, obj.minute, obj.second, obj.millisecond);
  return +d;
}

