function oldImpl(obj) {
  let d = Date.UTC(obj.year, obj.month - 1, obj.day, obj.hour, obj.minute, obj.second, obj.millisecond);
  if (obj.year < 100 && obj.year >= 0) { d = new Date(d); d.setUTCFullYear(d.getUTCFullYear() - 1900); }
  return +d;
}
function newImpl(obj) {
  const d = new Date(0);
  d.setUTCFullYear(obj.year, obj.month - 1, obj.day);
  d.setUTCHours(obj.hour, obj.minute, obj.second, obj.millisecond);
  return +d;
}
const o = {year: 2019, month: 5, day: 25, hour: 9, minute: 23, second: 54, millisecond: 123};
const o2 = {year: 99, month: 5, day: 25, hour: 9, minute: 23, second: 54, millisecond: 123};
for (const [name, fn] of [["old", oldImpl], ["new", newImpl]]) {
  for (const obj of [o, o2]) {
    const t0 = process.hrtime.bigint();
    let s = 0;
    for (let i = 0; i < 2000000; i++) s += fn(obj);
    const t1 = process.hrtime.bigint();
    console.log(`${name} year=${obj.year}: ${Number(t1 - t0) / 1e6} ms (checksum ${s})`);
  }
}
